rounds=[]
for n in [1,2]:
 suites=[]
 for prefix in ['native','validation','acceptance','v3','v3-content']:
  name=f'{prefix}-v3-final-{n}.json';d=json.loads((docs/name).read_text());suites.append({'suite':prefix,'file':name,'passed':sum(t['pass'] for t in d['tests']),'total':len(d['tests'])});assert all(t['pass'] for t in d['tests'])
 rounds.append({'round':n,'suites':suites,'passed':sum(s['passed'] for s in suites),'total':sum(s['total'] for s in suites)})
old=root.parent.parent/'v2-work/project/aem-eds-inter-toranja/vendor';vendor=root/'vendor';checked=0
for f in vendor.rglob('*'):
 if f.is_file():
  baseline=old/f.relative_to(vendor)
  assert baseline.exists() and hashlib.sha256(f.read_bytes()).digest()==hashlib.sha256(baseline.read_bytes()).digest(),str(f)
  checked+=1
